------------Event
function GamePlayGuideMgr:InitListener()
    self.eventBattleTurnStartShow = Events.AddListener(Constants.EventNames.BattleGuideStart, Bind(self, self.SelectPlay))
    self.eventBattleFinishedInput = Events.AddListener(Constants.EventNames.UIBattleGuideRoundStart, function(bool)
        self.battleRoundStart = bool
        KTool.SetActive(self.refGuideDialog.Layer_ShowElement.gameObject, bool)
        KTool.SetActive(self.refGuideDialog.Layer_Mask.gameObject, bool)
        if self.refGuideDialog and self.refGuideDialog.Layer_Mask then
            self.refGuideDialog.Layer_Mask:ResetMaterial()
        end
    end)
end

function GamePlayGuideMgr:RemoveListener()
    Events.RemoveListener(Constants.EventNames.BattleGuideStart, self.eventBattleTurnStartShow)
    Events.RemoveListener(Constants.EventNames.UIBattleGuideRoundStart, self.eventBattleFinishedInput)
    if not IsNull(self.eventBattleMyCard) then
        Events.RemoveListener(Constants.EventNames.BattleMyCard, self.eventBattleMyCard)
        self.eventBattleMyCard = nil
    end
end
