---DoSpecialActionOnStart
---在步骤 开始执行时 功能函数
function GamePlayGuideMgr:DoSpecialActionOnStart()
    local spFunc
    if self.specialId > 0 then
        local actionId = tostring(self.specialId)
        if KeySpecialAction[actionId] and KeySpecialAction[actionId].actionOnStart then
            spFunc = KeySpecialAction[actionId].actionOnStart
        end
    end
    if not IsNull(spFunc) then
        spFunc()
    end
end

---DoSpecialAction
---在步骤 执行时 功能函数
function GamePlayGuideMgr:DoSpecialAction()
    local spFunc
    if self.specialId > 0 then
        local actionId = tostring(self.specialId)
        if KeySpecialAction[actionId] and KeySpecialAction[actionId].action then
            spFunc = KeySpecialAction[actionId].action
        end
    end
    if not IsNull(spFunc) then
        -- 临时生成的对象可以返回出来，步骤结束以后自动给销毁掉
        local go = spFunc(self.refGuideDialog.Layer_ShowElement)
        if isNotNull(go) then
            self:AddOBJToListTempGO(go)
        end
    end
end

