end

---CheckPlaySequence
---检查剧本执行步骤
function GamePlayGuideMgr:CheckPlaySequence()
    if self.listPlayStepSequence and table.count(self.listPlayStepSequence) > 0 and self.battleRoundStart then
        self.guideIsRunning = true
        -- print("->GamePlayGuideMgr:CheckPlaySequence", table.count(self.listPlayStepSequence) > 0, UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().booleanPlayerRoundIsStart)
        --- 临时开关 射线遮挡层
        --- 后续需要知道 头 && 尾
        self.refGuideDialog:SetRaycastReceiverShowState(true)
        --- 剧本执行中
        self.coDoGuideStep = cs_coroutine.start(function()
            xpcall(function()
                self.stepId = self.listPlayStepSequence[1]
                local succeed = self:ValidatePlayable(self.stepId)  -- 验证是否可以播放
                if succeed then
                    cs_coroutine.yield_return(self:SelectPlayStep(self.stepId))
                end
                table.remove(self.listPlayStepSequence, 1)
                self:ActionOnFinishStep()
                --- 稳定性待测试
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                --- 发送服务器步骤Id
                if self.stepId then
                    --- 模块 id
                    local partId = 0
                    GameUtils.RecordGuideStep({ guideId = partId, guideStepId = self.stepId })
                end
                self.coDoGuideStep = nil
                self:CheckPlaySequence()
            end, function(msg)
                print(debug.traceback())
                if self.refGuideDialog then
                    self.refGuideDialog:SetBtnSafeExitState(true)
                end
            end)
        end)
    else
        self:CleanSuspendDialog()
        -- print("->当前回合引导步骤结束")
        --- 打断角色语音
        CriWareUtils.PlayVoice("Audio/UI_Menu", "empty")
        self.refGuideDialog:SetPanelElementShowState(false)
        local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        local finishRound = checkBool(battlingDialog.boolGuideRoundFinish)
        if finishRound then
            -- 当前回合剧本全部执行完毕，结束回合
            battlingDialog:ActionOnMyPlayerInputFinish()
        end
        if self.curWave and self.curWave >= #self.dataPlay
        and self.curRound and self.curRound >= #self.dataPlay[self.curWave]
        and self.listPlayStepSequence and table.count(self.listPlayStepSequence) <= 0 then
            --- 剧本执行完
            -- print("->引导剧本跑完了")
            --- 打断角色语音
            CriWareUtils.PlayVoice("Audio/UI_Menu", "empty")
            --self.refGuideDialog:SetRaycastReceiverShowState(false)
            UIBattleSettingMgr:HandleBattleInfoSetting()
            battlingDialog:InitPlayerSettingBtns()
            --UIBattlingCtrlMgr:GetInstance():GetBattlingDialog():SetPlayerPrefsBtnInteractable(true)
            KTool.SetActive(self.refGuideDialog.Container.gameObject,false)
            self.guideIsRunning = false
        end
        self.refGuideDialog:SetRaycastReceiverShowState(false)
    end
end
