---SelectPlay
---选择剧本
function GamePlayGuideMgr:SelectPlay()
    --self.coWaitBattleStartAnimation = cs_coroutine.start(function()
    --    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
    --end)

    -- 切换波次时，回合数清零
    local wave = UIBattlingCtrlMgr:GetInstance():GetBattleWave()
    if self.curWave ~= wave then
        self.curRound = 0
    end
    self.curWave = wave                 -- 记录波次
    self.curRound = self.curRound + 1   -- 记录回合
    print("[引导] 选择剧本", self.curWave, self.curRound, table.dump(self.dataPlay, nil, 3))

    if self.dataPlay[self.curWave] and self.dataPlay[self.curWave][self.curRound] then
        -- 有剧本的回合
        self.listPlayStepSequence = self.dataPlay[self.curWave][self.curRound]
        KTool.SetActive(self.refGuideDialog.Layer_ShowElement.gameObject, true)
        UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().boolGuideRoundFinish = false
        self.battleRoundStart = true
        self.indexRound = 0
        UIBattlingTools.ClosePopDialog(Constants.UITypeIds.UIBattlingCharactorInfoDialog)
        if isNull(self.listPlayStepSequence) then return end
        self:CheckPlaySequence()
    else
        -- 没剧本的回合，关闭引导
        KTool.SetActive(self.refGuideDialog.Container.gameObject,false)
    end
end

---StepDelayByConf
---配表延时
---@param value number 延时时长
function GamePlayGuideMgr:StepDelayByConf(value)
    if value > 0 then
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(value))
    end
end

function GamePlayGuideMgr:HandleSequenceWait()
    if checkBool(self.battlingDialogIsWait) then
        self.battlingDialogIsWait = false
        for i = 1, 2 do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
    end
    if checkNumber(self.specialId) == 10 then
        self.battlingDialogIsWait = true
    end
end

---SelectPlayStep
---选择演示幕
---@param playIndex integer @ 幕编号
function GamePlayGuideMgr:SelectPlayStep(stepId)
    print("[引导] 选择步骤", stepId)
    self.playData = GamePlayGuideConfMgr:GetGuideStepData(stepId)
    self.specialId = self.playData.special
    
    self:CleanGuideBook()
    self:ActionShowGuideBook()
    
    if self.indexRound < 1 then
        cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(1))
        if self:IsChapterZero() then
            cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(1))
        end
        self.indexRound = self.indexRound + 1
    end
    --print(table.dump(self.playData, "playData"))
    if self.playData and self.playData.stepDelay then
        self:StepDelayByConf(self.playData.stepDelay)
    end
    --- 描述
    local role = self.playData.role
    --- 讲解文字位置
    local rolePosData = self.playData.rolePos
    local rolePos = rolePosData.position
    local rolePosOffset = rolePosData.offset
    --- 讲解文字 标题
    local descTitle = self.playData.title
    --- 讲解文字 描述
    local desc = self.playData.desc
    local strTrigger = checkString(self.playData.action)
    self.dataDesc  = {
        role = role,
        rolePos = rolePos, 
        posOffset = rolePosOffset,
        descTitle = descTitle,
        desc = desc,
        strTrigger = strTrigger,
    }
    self.descShowType = Tools.isNullKey(rolePos) or rolePos < 1 and self.DESC_SHOW_TYPE.POS_RECT or self.DESC_SHOW_TYPE.POS_CONFIG
    self.ifFrame = checkNumber(self.playData.ifFrame)

    if self.coShowGuider then
        cs_coroutine.stop(self.coShowGuider)
    end
    --self.coShowGuider
    if self.descShowType == self.DESC_SHOW_TYPE.POS_CONFIG then
        self.coShowGuider = cs_coroutine.start(function()
            --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            --- 设置讲解文字 
            self.refGuideDialog:ShowGuideText(desc, self.dataDesc, descTitle)
            xTry(function()
                ---讲解员音频
                local voiceId = checkString(self.playData.voice)
                UIBattlingTools.PlaySE(voiceId)
            end)
        end)
    end
    
    --- 高亮
    local passType = self.playData.type --- 步骤类型
    self.highLightAreaData = self.playData.highLightAreas --- 区域类型
    self.highLightAreaPos = self.playData.interactableAreas --- 区域位置
    local listHighLight = {}

    local _stepData = GamePlayGuideConfMgr:GetGuideStepData(self.stepId)
    local _regionCoordinate = _stepData.regionCoordinate
    for i = 1, #self.highLightAreaData do
        local highLightArea = self:GetHighLightArea(self.highLightAreaData[i], self.highLightAreaPos[i], passType)

        if highLightArea then
            -- 判断是否有坐标和size的修改
            local coordModify = _regionCoordinate[i]
            local hasOffsetModify = not isNull(coordModify) and not IsNull(coordModify.positionOffset)
            local hasSizeModify = not isNull(coordModify) and not isNull(coordModify.size) and coordModify.size[1] ~= -1 and coordModify.size[2] ~= -1
            -- print("[引导] highLightArea", highLightArea, hasOffsetModify, hasSizeModify, table.dump(_regionCoordinate, nil, 3))
            -- 计算最终位置
            local RT = KTool.GetOrAddComponent(highLightArea.gameObject, typeof(RectTransform))
            local finalPos = RT.position
            local finalSize = hasSizeModify and Vector2.New(coordModify.size[1], coordModify.size[2]) or RT.rect.size
            local parent = passType == InteractableType.Click and self.refGuideDialog.Layer_Interactable or self.refGuideDialog.Layer_ShowElement
            local offsetX = hasOffsetModify and coordModify.positionOffset[1] or 0
            local offsetY = hasOffsetModify and coordModify.positionOffset[2] or 0

            highLightArea = self:CreateHighLightWithPOS(finalPos, finalSize, parent, "HighLightArea", offsetX, offsetY)
        end
        
        table.insert(listHighLight, highLightArea)
    end
    
    -- 如果交互类型是点击或者长按，收集点击位置
    if passType == InteractableType.Click or passType == InteractableType.LongTap then
        self.listStepClick = {}
        for i = 1, #self.highLightAreaData do
            if self.highLightAreaData[i] == Area.SkillsPool then
                if self.highLightAreaPos[i] ~= SkillsPoolAreas.UnitCombo then
                    --- 收集需要点击的技能卡
                    local pos = self.highLightAreaPos[i] --- 区域 和 位置 一一对应
                    local skillCardLocal = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().luaTableDialogSkillPool:GetSkillCardByPos(pos > 5 and 2 or 1, pos > 5 and pos - 5 or pos) --- 玩家技能池位置
                    table.insert(self.listStepClick, skillCardLocal)
                end
            elseif self.highLightAreaData[i] == Area.Enemy then
                table.insert(self.listStepClick, listHighLight[i])
            elseif self.highLightAreaData[i] == Area.ActionPoint then
                table.insert(self.listStepClick, listHighLight[i])
            --elseif self.highLightAreaData[i] == Area.AddBuffIcon then
            --    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
            --    self.listStepClick = battlingDialog:GetListAddBuffSign()
            elseif self.highLightAreaData[i] == Area.TopRoot then
                table.insert(self.listStepClick, listHighLight[i])
            elseif self.highLightAreaData[i] == Area.BossInfo then
                table.insert(self.listStepClick, listHighLight[i])
            elseif self.highLightAreaData[i] == Area.SkillCatBtn then
                local luaTBBattlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
                local go = luaTBBattlingDialog.RT_SkillCatNode.gameObject
                table.insert(self.listStepClick, go)
            end
        end
    end

    --- 高亮需要高亮的区域
    local highlightType = self.playData.highType

    --- 特殊操作在当前步骤开始
    self:DoSpecialActionOnStart()

    --- 跳步
    if passType == InteractableType.PassBtn then
        if listHighLight and #listHighLight > 1 then
            self.refGuideDialog:SetMaskDefault()
            self.refGuideDialog:SetImgHighLightPlural(listHighLight)    -- 设置高亮框
            self.refGuideDialog:ShowImgHighLightPlural()                -- 高亮框播放动画
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            self.refGuideDialog:SetHighLightPlural(listHighLight)   -- 在遮黑蒙版上，用shader抠出透明区域
        elseif listHighLight and #listHighLight == 1 then
            local go = listHighLight[1]
            if isNull(go) then return end
            --- 高亮动效
            self.rectTarget = go:GetComponent(typeof(RectTransform))
            if self.rectTarget then
                self.refGuideDialog:SetHighLightShow(self.rectTarget)
            end
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            self:SetPTCGuideMove(self.rectTarget.transform.position)
            self.refGuideDialog:SetPosImgHighLight(go)
        end
        self:SetClickDialogPass()
    elseif passType == InteractableType.Click then
        --- 点击技能牌
        --- 高亮动效
        if self.highLightAreaData[1] == Area.SkillsPool then
            if self.highLightAreaPos[1] == SkillsPoolAreas.UnitCombo then
                --- 点击 合卡技 区域
                local goRoot = listHighLight[1]
                self.rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
                if self.rectTarget then
                    self.refGuideDialog:SetHighLightShow(self.rectTarget)
                end
                self:SetPTCGuideMove(self.rectTarget.transform.position)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                self.refGuideDialog:SetPosImgHighLight(goRoot)
                self:ScreenPosClickEntry(goRoot)
            else
                --- 点击技能牌
                if not IsNull(listHighLight[1]) then
                    local rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
                    if rectTarget then
                        --- 设置高亮动效
                        self.refGuideDialog:SetHighLightShow(rectTarget)
                    end
                    --- 红框位置
                    local scale = self.skillPoolScale and Vector2.New(self.skillPoolScale.x, self.skillPoolScale.y) or Vector2.New(1,1)
                    self.refGuideDialog:SetImgHighLightWithData(Vector2.New(IMAGE_SKILL_CARD_SIZE.x * scale.x, IMAGE_SKILL_CARD_SIZE.y * scale.y), rectTarget.transform.position)
                    --- 点击 Icon 位置
                    self.refGuideDialog:SetPosGOStepIconClick(rectTarget.gameObject)
                    self:SetPTCGuideMove(rectTarget.transform.position)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                    while self.refGuideDialog.Layer_Mask.CoShowFocus do
                        cs_coroutine.yield_return()
                    end
                    self:SkillCardClickEntry()
                end
            end
        elseif self.highLightAreaData[1] == Area.Enemy then
            --- 敌方人物
            if not IsNull(listHighLight[1]) then
                local rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
                if rectTarget then
                    self.refGuideDialog:SetHighLightShow(rectTarget)
                end
                self:SetPTCGuideMove(rectTarget.transform.position)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                self.refGuideDialog:SetPosImgHighLight(listHighLight[1])
                --- 绑定 人物 点击事件
                self:CharacterClickEntry(passType)
            end
        elseif self.highLightAreaData[1] == Area.ActionPoint then
            --- 行动点区域
            if self.highLightAreaPos[1] == PassRoundType then
                local rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
                if rectTarget then
                    self.refGuideDialog:SetHighLightShow(rectTarget)
                end
                self:SetPTCGuideMove(rectTarget.transform.position)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                self.refGuideDialog:SetPosImgHighLight(listHighLight[1])
                if tostring(self.playData.special) == "6" then
                    self:PassRoundBtnSureClick(listHighLight[1])
                else
                    self:PassRoundBtnClick()
                end
            else
                --- 点击重置卡牌
                local rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
                if rectTarget then
                    self.refGuideDialog:SetHighLightShow(rectTarget)
                end
                self:SetPTCGuideMove(rectTarget.transform.position)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                self.refGuideDialog:SetPosImgHighLight(listHighLight[1])
                --- 绑定 按钮点击事件
                self:ReSetSkillCardBtnClick()
            end
        elseif self.highLightAreaData[1] == Area.AddBuffIcon then
            --- 友方Buff
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            self:SetAddBuffStep()
        elseif self.highLightAreaData[1] == Area.TopRoot then
            local go = listHighLight[1]
            if not IsNull(go) then
                local rectTarget = go:GetComponent(typeof(RectTransform))
                if self.specialId == 9 then
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.12))
                end
                --- 设置高亮动效
                self.refGuideDialog:SetHighLightShow(rectTarget)
                --- 红框位置
                self.refGuideDialog:SetImgHighLightWithData(rectTarget.sizeDelta, rectTarget.transform.position)
                --- 点击 Icon 位置
                self.refGuideDialog:SetPosGOStepIconClick(rectTarget.gameObject)
                self:SetPTCGuideMove(rectTarget.transform.position)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
                while self.refGuideDialog.Layer_Mask.CoShowFocus do
                    cs_coroutine.yield_return()
                end
                local listStep = clone(self.highLightAreaPos)
                self:TopRootClickEntry(listStep)
            end
        elseif self.highLightAreaData[1] == Area.BossInfo then
            local goRoot = listHighLight[1]
            self.rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
            if self.rectTarget then
                self.refGuideDialog:SetHighLightShow(self.rectTarget)
            end
            self:SetPTCGuideMove(self.rectTarget.transform.position)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            self.refGuideDialog:SetPosImgHighLight(goRoot)
            self:BossInfoClickEntry(goRoot)
        elseif self.highLightAreaData[1] == Area.SkillCatBtn then
            local go = listHighLight[1]
            self.refGuideDialog:SetPosImgHighLight(go)  -- 高亮框
            local rectTarget = go:GetComponent(typeof(RectTransform))
            if rectTarget then
                --- 设置高亮区域
                self.refGuideDialog:SetHighLightShow(rectTarget)
            end
            -- self.refGuideDialog:SetPosGOStepIconClick(rectTarget.gameObject)     -- 点击icon
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            while self.refGuideDialog.Layer_Mask.CoShowFocus do
                cs_coroutine.yield_return()
            end
            self:SkillCatBtnClickEntry()
        end
    elseif passType == InteractableType.Drag then
        self:GetSliderType()
        if self.typeSlider == SliderType.Vertical or self.typeSlider == SliderType.Horizontal then
            self:CommonSlider(listHighLight)
        else
            self:FreeSlider(listHighLight)
        end
    elseif passType == InteractableType.LongTap then
        if not IsNull(listHighLight[1]) then
            local rectTarget = listHighLight[1]:GetComponent(typeof(RectTransform))
            if rectTarget then
                self.refGuideDialog:SetHighLightShow(rectTarget)
            end
            self:SetPTCGuideMove(rectTarget.transform.position)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            self.refGuideDialog:SetPosImgHighLight(listHighLight[1])
            self:LongTapEntry()
        end
    end
    self:HandleSequenceWait()
    --- 特殊操作在步骤结尾
    self:DoSpecialActionOnStepEnd()
end

function GamePlayGuideMgr:GetSliderType()
    self.typeSlider = SliderType.Horizontal
    if checkNumber(self.specialId) > 0 then
        if self.specialId == SliderHorizontalKey then
            self.typeSlider = SliderType.Vertical
        elseif self.specialId == FreeSlider then
            self.typeSlider = SliderType.Free
        end
    end
end

function GamePlayGuideMgr:FreeSlider(listHighLight)
    
    if listHighLight and #listHighLight > 1 then
        self.refGuideDialog:SetMaskDefault()
        self.refGuideDialog:SetImgHighLightPlural(listHighLight)
        self.refGuideDialog:ShowImgHighLightPlural()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        self.refGuideDialog:SetHighLightPlural(listHighLight)
    end
    
    local data = self.highLightAreaPos
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local tableSkillCard = battlingDialog.luaTableDialogSkillPool
    
    local ctrLine, ctrPos = self:GetSkillCardPosInSkillPool(data[1])
    local aimLine, aimPos = self:GetSkillCardPosInSkillPool(data[2])
    
    local skillCardVo_Pos1 = tableSkillCard:GetSkillCardByPos(ctrLine, ctrPos)
    local skillCard_1 = skillCardVo_Pos1.luaBehaviour
    self.freeDragOriginPos = skillCardVo_Pos1.position
    local skillCardVo_Pos2 = tableSkillCard:GetSkillCardByPos(aimLine, aimPos)
    local skillCard_2 = skillCardVo_Pos2.luaBehaviour
    self.freeDragTargetPos = skillCardVo_Pos2.position
    
    ---确定拖拽图标坐标
    --local iconPos = Vector3.New((skillCard_1.transform.position.x + skillCard_2.transform.position.x) / 2,
    --        (skillCard_1.transform.position.y + skillCard_2.transform.position.y) / 2,
    --        (skillCard_1.transform.position.z + skillCard_2.transform.position.z) / 2)
    --- 确定拖拽图标 Z 轴旋转
    --local numIconRotation = self.typeSlider == SliderType.Horizontal and 180 or -90
    --self.refGuideDialog:SetPosGOStepIconSlide(iconPos, numIconRotation)
    
    self.dragSkillCard = skillCard_1
    local rectOriginSkillsPool = battlingDialog.SkillCardsPool
    local goSkillsPool = KTool.CreateEmptyGameObject(self.refGuideDialog.Layer_Interactable.gameObject, "SkillCardRoot")
    
    goSkillsPool.transform.position = rectOriginSkillsPool.transform.position
    goSkillsPool.transform.localScale = rectOriginSkillsPool.transform.localScale
    local eulerAngles = rectOriginSkillsPool.transform.localRotation.eulerAngles
    
    goSkillsPool.transform.localRotation = Quaternion.Euler(eulerAngles.x, eulerAngles.y, eulerAngles.z)
    local rectSkillsPool = KTool.GetOrAddComponent(goSkillsPool, typeof(RectTransform))
    rectSkillsPool.sizeDelta = rectOriginSkillsPool.sizeDelta
    local skillCardController = self:CreateSkillCardGO(skillCard_1, goSkillsPool.gameObject, "DragSkillCard")
    skillCardController.transform.localRotation = Quaternion.Euler(0, 0, 90)
    
    --self.eventBattleMyCard = Events.AddListener(Constants.EventNames.BattleMyCard, function(data)
    --    if data.r == Constants.RecordType.MoveCard then
    --        self.booleanIsYield = false
    --    end
    --end)
    
    KTool.GetOrAddComponent(skillCardController, typeof(GraphicRaycastReceiver))
    
    local skillCardPos_1 = skillCardVo_Pos1.position.position
    local skillCardPos_2 = skillCardVo_Pos2.position.position
    local posIcon = Vector3.New((skillCardPos_1.x + skillCardPos_2.x)/2, (skillCardPos_1.y + skillCardPos_2.y)/2, (skillCardPos_1.z + skillCardPos_2.z)/2)
    local dir = (skillCardPos_2 - skillCardPos_1).normalized
    local angle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
    angle = angle < 0 and  angle + 360 or angle;
    local r = Mathf.Atan2(Vector3.Distance(Vector3.zero,Vector3.Cross(skillCardPos_2.normalized,skillCardPos_1.normalized))) * Mathf.Rad2Deg;
    self.refGuideDialog:SetPosGOStepIconSlide(posIcon, angle - 90)
    self:AddDragFun(skillCardController, true)
    self:AddOBJToListTempGO(skillCardController)
    self:YieldFunction()
end

function GamePlayGuideMgr:CommonSlider(listHighLight)
    local rectSkillCard_1 = listHighLight[1]:GetComponent(typeof(RectTransform))
    local rectSkillCard_2 = listHighLight[2]:GetComponent(typeof(RectTransform))
    local aimSize --- 控制器大小
    local aimPos --- 控制器位置
    local highLightArea --- 高亮区域 位置
    local rectTarget
    if self.typeSlider == SliderType.Horizontal then
        --- 确定高亮框的大小 && 位置
        aimSize = Vector2.New(rectSkillCard_1.rect.width + 6,
                rectSkillCard_1.rect.height + rectSkillCard_2.rect.height)
        aimPos = Vector3.New((rectSkillCard_1.position.x + rectSkillCard_2.position.x) / 2,
                (rectSkillCard_1.position.y + rectSkillCard_2.position.y) / 2,
                (rectSkillCard_1.position.z + rectSkillCard_2.position.z) / 2)
    else
        aimSize = Vector2.New(rectSkillCard_1.rect.width + rectSkillCard_2.rect.width + 6,
                rectSkillCard_1.rect.height + 3)
        aimPos = Vector3.New((rectSkillCard_1.position.x + rectSkillCard_2.position.x) / 2,
                (rectSkillCard_1.position.y + rectSkillCard_2.position.y) / 2,
                (rectSkillCard_1.position.z + rectSkillCard_2.position.z) / 2)
    end
    highLightArea = self:CreateHighLightWithPOS(aimPos, aimSize, self.refGuideDialog.Layer_ShowElement, "DragHighLightArea", 0, 0)
    rectTarget = highLightArea:GetComponent(typeof(RectTransform))
    if rectTarget then
        self.refGuideDialog:SetHighLightShow(rectTarget)
    end
    self:SetPTCGuideMove(rectTarget.transform.position)
    cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(0.3))
    self.refGuideDialog:SetImgHighLightWithData(aimSize, aimPos)
    cs_coroutine.yield_return(CS.UnityEngine.WaitForSecondsRealtime(1))
    self:ShowMoveSkillCard(self.highLightAreaPos)
end

---SetClickDialogPass
---点击屏幕跳过
function GamePlayGuideMgr:SetClickDialogPass()
    ---打开跳步按钮
    self.refGuideDialog:SetBtnToNextShowState(true)
    ---出现跳步点击区域
    self:YieldFunction()
end

---YieldFunction
---步骤暂停
function GamePlayGuideMgr:YieldFunction()
    self:DoSpecialAction()
    self.booleanIsYield = true
    while self.booleanIsYield do
        cs_coroutine.yield_return()
    end
end

---ScreenPosClickEntry
---屏幕位置点击跳过
function GamePlayGuideMgr:ScreenPosClickEntry(gameObject)
    local tempGO = self:CreateClickGO(gameObject, self.refGuideDialog.Layer_Interactable, "UnitCombo", nil)
    self.refGuideDialog:SetPosGOStepIconClick(gameObject)
    self:AddOBJToListTempGO(tempGO)
    self:YieldFunction()
    self:ClearTempGO()
end

---TopRootClickEntry
---@param dataStep table {1,2,3} 执行步骤
function GamePlayGuideMgr:TopRootClickEntry(dataStep)
    local sequenceStep = dataStep
    --- 技能卡生成位置
    local goBtn = self.listStepClick[1].gameObject
    --- 卡牌选择回调
    local curStep = sequenceStep[1]
    local func = self:SelectBindFunc(curStep)
    local tempGO = self:CreateClickGO(goBtn, self.refGuideDialog.Layer_Interactable, "TopBtn", Bind(self, func))
    --- 设置按键层级需要特殊设置
    if curStep == TopAreaType.Setting then
        local compCanvas = KTool.GetOrAddComponent(tempGO, typeof(Canvas))
        KTool.GetOrAddComponent(tempGO, typeof(CS.UnityEngine.UI.GraphicRaycaster))
        if compCanvas then
            compCanvas.overrideSorting = true
            compCanvas.sortingOrder = 3400
        end
    end
    self:AddOBJToListTempGO(tempGO)
    ---出现跳步点击区域
    self:YieldFunction()
    if self.refGuideDialog then
        self.refGuideDialog:ClearRefTarget()
    end
    self:ClearTempGO()
    self:RevertComponent()
    table.remove(self.listStepClick, 1)
    table.remove(sequenceStep, 1)
    self:CheckTopBtnSequence(sequenceStep)
end

function GamePlayGuideMgr:BossInfoClickEntry()
    --- 技能卡生成位置
    local goBtn = self.listStepClick[1].gameObject
    local _func = function()
        UIBattlingCtrlMgr:GetInstance():GetEleBreakLuaTable():ActionOnBtnShowInfoClick()
    end
    local tempGO = self:CreateClickGO(goBtn, self.refGuideDialog.Layer_Interactable, "BossInfo", Bind(self, _func))
    self:AddOBJToListTempGO(tempGO)
    ---出现跳步点击区域
    self:YieldFunction()
    if self.refGuideDialog then
        self.refGuideDialog:ClearRefTarget()
    end
    self:ClearTempGO()
    self:RevertComponent()
end

---SelectBindFunc
---设置战中游戏设置函数
---@param type integer @ TopAreaType 事件类型
function GamePlayGuideMgr:SelectBindFunc(type)
    local battlingDialog =  UIBattlingCtrlMgr:GetInstance():GetBattlingDialog() -- BattlingDialog 引用
    local bindFuncList = { 
        [TopAreaType.Auto] = Bind(battlingDialog, battlingDialog.OnBtnAutoClick),
        -- [TopAreaType.Skip] = Bind(battlingDialog, battlingDialog.OnBtnSkillSkipClick),
        [TopAreaType.DoubleRate] = Bind(battlingDialog,battlingDialog.OnBtnDoubleRateClick),
        [TopAreaType.Setting] = Bind(battlingDialog, battlingDialog.GameOver)
    }
    if self.specialId == 9 then
        return function()
            local dialogs = UIModule.CurrentScreen.dialogs
            for i, dialog in pairs(dialogs) do
                if dialog.Argument.id == Constants.UITypeIds.UIGamePlayGuideBookDialog then
                    local lt = dialog.Env
                    if lt then
                        lt:SwitchTabBtn(2)
                    end
                end
            end
        end
    end
    return bindFuncList[type] or function()  end
end

function GamePlayGuideMgr:CheckTopBtnSequence(sequenceStep)
    if #self.listStepClick > 0 then
        local btn = self.listStepClick[1].gameObject
        self:SetShowAreaComponent(btn.gameObject)
        local rectBtn = btn:GetComponent(typeof(RectTransform))
        local tempHighLight = self:CreateHighLightWithPOS(btn.transform.position, rectBtn.sizeDelta,
                self.refGuideDialog.Layer_ShowElement, "TopBtn", 0, 0)
        local rectTarget = tempHighLight:GetComponent(typeof(RectTransform))
        if rectTarget then
            self.refGuideDialog:SetHighLightShow(rectTarget, true)
        end
        --- DOTween 位移动画
        self.refGuideDialog:SetImgHighLightMove(btn.transform)
        --- 设置点击 Icon
        self.refGuideDialog:SetPosGOStepIconClick(btn.gameObject)
        --- 获取当前 时间缩放 改变延时
        local TimeScaleNow = Time.timeScale
        local timeDelay = (TimeScaleNow and TimeScaleNow > 5) and 1 or 0.3
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(timeDelay))
        --- 判断技能卡库位置 lb 是否有值，无值等待
        if IsNull(self.listStepClick[1].gameObject) then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        end
        --- 卡牌选择回调
        local curStep = sequenceStep[1]
        local func = self:SelectBindFunc(curStep)
        local tempGO = self:CreateClickGO(btn, self.refGuideDialog.Layer_Interactable, "TopBtn", Bind(self, func))
        self:AddOBJToListTempGO(tempGO)
        ---出现跳步点击区域
        self:YieldFunction()
        if self.refGuideDialog then
            self.refGuideDialog:ClearRefTarget()
        end
        self:ClearTempGO()
        self:RevertComponent()
        table.remove(self.listStepClick, 1)
        table.remove(sequenceStep, 1)
        self:CheckTopBtnSequence(sequenceStep)
    else
        --TODO 完成所有点击
        --TODO 高亮红框，手指 消失
