---CharacterClickEntry
---人物点击入口
function GamePlayGuideMgr:CharacterClickEntry()
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local characterType = self.highLightAreaData[1]
    local areaClick = self.listStepClick[1]
    local idCharacter = self.listIdsCharacter[1]
    if IsNull(areaClick) or IsNull(idCharacter) then return end
    local func --- 点击事件
    if characterType == Area.Enemy then
        func = function()
            battlingDialog:ClearAttackTarget()
            battlingDialog:SetAttackSignState(idCharacter)
        end
    elseif characterType == Area.Character then
        func = function()
            battlingDialog:OnSelectAddBuffCharactorLogic(idCharacter)
        end
    end
    self:AddClickComponent(areaClick, Bind(self, func))
    if (not IsNull(self.listStepClick)) and  #self.listStepClick > 0 then
        self:YieldFunction()
    end
    self:ClearTempGO()
end

