---SetAddBuffStep
---设置队伍添加 Buff 的跳步步骤
function GamePlayGuideMgr:SetAddBuffStep()
    --- BattlingDialog 的 LuaTabe
    local luaTBBattlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local roleInfoGroup = luaTBBattlingDialog.BattleRoleIInfoGroup.Env
    --- 获取人物 Buff 添加按钮 游戏物体 对象集合
    local listAddBuffSign = roleInfoGroup.listRoleInfo
    local listRoot = {}
    for i, node in pairs(listAddBuffSign) do
        local goNode = node.controller.gameObject

        --- 计算一下角色头像的大小
        local goRect = goNode:GetComponent(typeof(RectTransform))
        local goSize = goRect.rect
        local scale = goRect.transform.localScale
        local sizeDelta = Vector2.New((goSize.width * scale.x) , (goSize.height * scale.y))

        local go2Show = self:CreateHighLightWithPOS(goNode.transform.position, sizeDelta,
    self.refGuideDialog.Layer_ShowElement, "RoleInfo"..checkString(i), 10, 0)
        table.insert(listRoot, go2Show)
    end
    self.refGuideDialog:SetMaskDefault()
    --- 红框高亮动画
    self.refGuideDialog:SetImgHighLightPlural(listRoot)
    self.refGuideDialog:ShowImgHighLightPlural()
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
    --- 获取战场玩家队伍数据
    local battlePlayerTeamData = UIBattlingDataMgr:GetPlayerTeamList()
    if not IsNull(listAddBuffSign) and #listAddBuffSign > 0 then
        --- shader
        self.refGuideDialog:SetHighLightPlural(listRoot)
        --- 头像游戏物体点击事件
        for i = 1, #listAddBuffSign do
            local roleInfoNode = listAddBuffSign[i]
            local goRoleInfoNode = roleInfoNode.controller.gameObject
            --local targetId =  roleInfoNode.roleId
            local funcSignClick = function()
                roleInfoNode.uiEventProxy.onPointerClick()
                --luaTBBattlingDialog:OnSelectAddBuffCharactorLogic(targetId or battlePlayerTeamData[i].id)
            end
            local tempGO = self:CreateClickGO(goRoleInfoNode, self.refGuideDialog.Layer_Interactable, "AddBuffSign_" .. i, Bind(self, funcSignClick))
            self:AddOBJToListTempGO(tempGO)
        end
        self:YieldFunction()
    end
    --- 清理临时预设
    self:ClearTempGO()
    --if (not IsNull(self.listStepClick)) and  #self.listStepClick > 0 then
    --    --- 出现跳步点击区域
    --    table.remove(self.listStepClick, 1)
    --end
end

