---CheckClickSequence
---检测连续点击 函数
function GamePlayGuideMgr:CheckClickSequence()
    if #self.listStepClick > 0 then
        local skillCardPos = self.listStepClick[1].position
        --TODO 不对技能卡设置层级
        --self:SetShowAreaComponent(skillCardPos.gameObject)   --待删除
        local tempHighLight = self:CreateHighLightWithPOS(skillCardPos.transform.position, SKILL_CARD_SIZE, self.refGuideDialog.Layer_ShowElement, "SkillCardArea", 0, 0)
        local rectTarget = tempHighLight:GetComponent(typeof(RectTransform))
        if rectTarget then
            self.refGuideDialog:SetHighLightShow(rectTarget, true)
        end
        --- DOTween 位移动画
        self.refGuideDialog:SetImgHighLightMove(skillCardPos.transform)
        --- 设置点击 Icon
        self.refGuideDialog:SetPosGOStepIconClick(skillCardPos.gameObject)
        --- 获取当前 时间缩放 改变延时
        local TimeScaleNow = Time.timeScale
        local timeDelay = (TimeScaleNow and TimeScaleNow > 5) and 1 or 0.3
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(timeDelay))
        --- 判断技能卡库位置 lb 是否有值，无值等待
        if IsNull(self.listStepClick[1].luaBehaviour) then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        end
        --- 还有未点击卡牌
        self.skillCardLB = self.listStepClick[1].luaBehaviour
        --- 获取技能卡对象LB
        local tableSkillCard = self.skillCardLB.Env
        --- 技能卡生成位置
        local skillCardGO = skillCardPos.gameObject
        --- 卡牌选择回调
        local skillSelect = function()
            tableSkillCard:SkillCardUse()
        end
        local tempGO = self:CreateClickGO(skillCardGO, self.refGuideDialog.Layer_Interactable, "SkillCard", Bind(self, skillSelect))
        self:AddOBJToListTempGO(tempGO)
        ---出现跳步点击区域
        self:YieldFunction()
        if self.refGuideDialog then
            self.refGuideDialog:ClearRefTarget()
        end
        self:ClearTempGO()
        self:RevertComponent()
        table.remove(self.listStepClick, 1)
        self:CheckClickSequence()
    else
        --TODO 完成所有点击
        --TODO 高亮红框，手指 消失
        --TODO 待优化
        self:ActionOnFinishStep()
    end
end

---CreateHighLightGO
---创建高亮 游戏物体
---@param srcGO UnityEngine.GameObject 克隆物体
---@param goFather UnityEngine.GameObject 克隆物体的父节点
---@param strGOName string 克隆物体名
function GamePlayGuideMgr:CreateHighLightGO(srcGO, goFather, strGOName)
    local goDst = KTool.CreateEmptyGameObject(goFather.gameObject, strGOName)
    goDst.transform.position = srcGO.transform.position
    local rectSrcGO = srcGO:GetComponent(typeof(RectTransform))
    local sizeSrcGO = rectSrcGO.sizeDelta
    local rectDstGO = KTool.GetOrAddComponent(goDst, typeof(RectTransform))
    rectDstGO.sizeDelta = sizeSrcGO
    -------------------TempShowPos
    self:AddOBJToListTempGO(goDst)
    return goDst
end

---CreateHighLightWithPOS
---@param pos Vector3 目标位置
---@param goFather UnityEngine.GameObject 克隆物体的父节点
---@param strGOName string 克隆物体名
---@return UnityEngine.GameObject
function GamePlayGuideMgr:CreateHighLightWithPOS(pos, sizeDelta, goFather, strGOName, offsetX, offsetY, isAnchoredPosition)
    local goDst = KTool.CreateEmptyGameObject(goFather.gameObject, strGOName)
    local posType = isAnchoredPosition and "anchoredPosition" or "position"
    pos = isAnchoredPosition and Vector2.New(pos.x, pos.y) or pos
    local rectDstGO = KTool.GetOrAddComponent(goDst, typeof(RectTransform))
    goDst.transform[posType] = pos
    rectDstGO.anchoredPosition = Vector2.New(rectDstGO.anchoredPosition.x + offsetX, rectDstGO.anchoredPosition.y + offsetY)
    rectDstGO.sizeDelta = sizeDelta
    self:AddOBJToListTempGO(goDst)
    -------------------TempShowPos
    return goDst
end

---CreateClickGO
---创建绑定点击事件的游戏物体
---@param srcGO UnityEngine.GameObject @ 克隆源物体
---@param goFather UnityEngine.GameObject @ 生成物体的父节点
---@param strGOName string  @生成物体名
---@param callback fun():void @ 生成物体的绑定函数
function GamePlayGuideMgr:CreateClickGO(srcGO, goFather, strGOName, callback)
    local goDst = self:CreateSkillCardGO(srcGO, goFather, strGOName)
    self:AddClickComponent(goDst, callback)
    return goDst
end

---AddClickComponent
---@param aimGO UnityEngine.GameObject @ 绑定点击的游戏物体
---@param callback fun():void @ 点击函数
function GamePlayGuideMgr:AddClickComponent(aimGO, callback)
    KTool.GetOrAddComponent(aimGO, typeof(CanvasRenderer))
    KTool.GetOrAddComponent(aimGO, typeof(GraphicRaycastReceiver))
    -------------------EventClick
    UIEventProxy.Create(aimGO).onPointerClick = function()
        if callback then
            callback()
        end
        GamePlayGuideMgr.booleanIsYield = false
    end
end

---CreateLongTapGO
---创建绑定长按事件的游戏物体
---@param srcGO UnityEngine.GameObject @ 克隆源物体
---@param goFather UnityEngine.GameObject @ 生成物体的父节点
---@param strGOName string @ 生成物体名
---@param callback fun():void @ 生成物体的绑定函数
function GamePlayGuideMgr:CreateLongTapGO(srcGO, goFather, strGOName, callback, pressEndCallback)
    self.isPressing = false

    local goDst = self:CreateSkillCardGO(srcGO, goFather, strGOName)
    KTool.GetOrAddComponent(goDst, typeof(CanvasRenderer))
    KTool.GetOrAddComponent(goDst, typeof(GraphicRaycastReceiver))

    -- 添加长按回调
    local compLongTap = KTool.GetOrAddComponent(goDst, typeof(QuickLongTap))
    compLongTap.onLongTap:AddListener(function()
        callback()
        self.isPressing = true
    end)

    -- 添加长按结束的回调
    --- 借用 UIDrag 的 TouchEnd
    local compDrag = KTool.GetOrAddComponent(goDst, typeof(UIDrag))
    compDrag.onDragEnd:AddListener(function()
        if self.isPressing then
            self.isPressing = false
            compLongTap.enabled = false
            compDrag.enabled = false

            if isNotNull(pressEndCallback) then
                pressEndCallback()
            end
        end
    end)
    return goDst, compLongTap
end

---CreateSkillCardGO
---@param srcGO UnityEngine.GameObject
---@param goFather UnityEngine.GameObject
---@param strGOName string
function GamePlayGuideMgr:CreateSkillCardGO(srcGO, goFather, strGOName)
    local goDst = KTool.CreateEmptyGameObject(goFather.gameObject, strGOName)
    goDst.transform.position = srcGO.transform.position
    local rectSrcGO = srcGO:GetComponent(typeof(RectTransform))
    local sizeSrcGO = rectSrcGO.sizeDelta
    local rectDstGO = KTool.GetOrAddComponent(goDst, typeof(RectTransform))
    rectDstGO.sizeDelta = sizeSrcGO
    return goDst
end

