---AddOBJToListTempGO
---@param obj UnityEngine.GameObject 添加的游戏物体
function GamePlayGuideMgr:AddOBJToListTempGO(obj)
    if IsNull(self.listTempGO) then
        self.listTempGO = {}
    end
    table.insert(self.listTempGO, obj)
end

---ClearTempGO
---清理上步出现的临时预制体
function GamePlayGuideMgr:ClearTempGO()
    if not IsNull(self.listTempGO) and #self.listTempGO > 0 then
        for i = #self.listTempGO, 1, -1 do
            KTool.SafeDelete(self.listTempGO[i])
            self.listTempGO[i] = nil
        end
        self.listTempGO = nil
    end
end


function GamePlayGuideMgr:GetPlayerTeamRoleInfoNode(id, passType)
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local roleInfoGroup = battlingDialog.BattleRoleIInfoGroup.Env
    local listRoleInfo = roleInfoGroup.listRoleInfo
    for i, roleInfo in pairs(listRoleInfo) do
        if roleInfo.roleAlive and roleInfo.roleId == id then
            return roleInfo.controller.gameObject
        end
    end
end


---GetBattleRoleById
---创建 人物位置 节点
---@param id UIBattlingSkillCardsNode
---@param typeCharacter table
---@param passType integer
---@return UnityEngine.GameObject
function GamePlayGuideMgr:GetBattleRoleById(id, typeCharacter, passType)
    local go
    local roleView = BattleViewMgr:FindRoleView(id)
    if roleView then
        local characterTrans = roleView.transform
        local characterCenterY = roleView.centerY
        local scale = characterTrans.localScale
        local rootFather = passType == InteractableType.Click and self.refGuideDialog.Layer_Interactable or self.refGuideDialog.Layer_ShowElement
        local vector2 = UIBattlingTools.WorldPointToUIPoint(Vector3.New(characterTrans.position.x, characterCenterY * scale.y, characterTrans.position.z), rootFather)
        go = self:CreateHighLightWithPOS(vector2, Vector2.New(200, typeCharacter == Area.Character and 380 or 220),
                rootFather, "CharacterPos_" .. id, 0, 40, true)
    end
    return go
end

