---GetHighLightArea
---@param type integer @ 区域类型(Conf region)
---@param pos integer @ 区域位置
---@param passType integer
---@return UnityEngine.GameObject
function GamePlayGuideMgr:GetHighLightArea(type, pos, passType)
    local go
    if type == Area.SkillsPool then
        --- 玩家技能池区域
        local luaTBBattlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        if pos == SkillsPoolAreas.SkillsPool then
            go = luaTBBattlingDialog.BottomRightPanel.gameObject
        elseif pos == SkillsPoolAreas.UnitCombo then
            local tablePanel = UIBattlingCtrlMgr:GetInstance():GetRefUnitComboPanel()
            if tablePanel then
                --local rootName = self.playData.special == 5 and "Root_SkillInfo" or "Root_ComboPoint"
                --go = UIBattlingCtrlMgr:GetInstance():GetRefUnitComboPanel()[rootName].gameObject
                if self.playData.special == 5 then
                    go = self.refGuideDialog.Area_Sp_5.gameObject
                else
                    go = UIBattlingCtrlMgr:GetInstance():GetRefUnitComboPanel().Root_ComboPoint.gameObject
                end
            end
        else
            --- 技能卡位置的游戏物体
            self.skillPoolScale = luaTBBattlingDialog.SkillCardsPool.gameObject.transform.localScale
            local skillCardLocal = luaTBBattlingDialog.luaTableDialogSkillPool:GetSkillCardByPos(pos > 5 and 2 or 1, pos > 5 and pos - 5 or pos).position.gameObject
            go = self:CreateHighLightWithPOS(skillCardLocal.transform.position, Vector2.New(SKILL_CARD_SIZE.x * self.skillPoolScale.x, SKILL_CARD_SIZE.y * self.skillPoolScale.y), self.refGuideDialog.Layer_ShowElement, "SkillCardArea", 0, 0)
        end
    elseif type == Area.ActionPoint then
        --- 玩家行动点区域
        if pos == 1 then
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().ReStartSelectCardBtn.gameObject
        elseif pos == 6 then
            if tostring(self.playData.special) == "6" then
                go = self.refGuideDialog.Area_Sp_6
            else
                go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().btnPassRound.controller.gameObject
            end
        else
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().BottomLeftPanel.gameObject
        end
    elseif type == Area.Character then
        --- 玩家队伍成员区域
        --go = self:GetBattleRoleById(pos, type, passType)
        -- go = self:GetPlayerTeamRoleInfoNode(pos, passType)
        local playerData = UIBattlingDataMgr:GetPlayerTeamList()
        local fieldId = playerData[pos].id
        if IsNull(self.listIdsCharacter) then
            self.listIdsCharacter = {}
        end
        --- 填充人物 IDs
        table.insert(self.listIdsCharacter, fieldId)
        go = self:GetBattleRoleById(fieldId, type, passType)
    elseif type == Area.Enemy then
        --- 敌方队伍成员区域
        -- local enemyData = UIBattlingDataMgr:GetEnemyTeamList()
        local enemyData = self:GetEnemyTeamByWave(self.curWave)
        local fieldId = enemyData[pos].id
        if IsNull(self.listIdsCharacter) then
            self.listIdsCharacter = {}
        end
        --- 填充人物 IDs
        table.insert(self.listIdsCharacter, fieldId)
        go = self:GetBattleRoleById(fieldId, type, passType)
    elseif type == Area.TopRoot then
        --- 玩家操作面板 顶部区域
        --- 属性克制 提示面板
        if pos == 5 then
            ---属性克制讲解按钮
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().AttributeCircleBtn.transform.gameObject
        elseif pos == 1 then
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().btnLBAutoGame.controller.gameObject
        elseif pos == 2 then
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().btnLBSkip.controller.gameObject
        elseif pos == 3 then
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().btnLBDoubleRate.controller.gameObject
        elseif pos == 4 then
            go = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().SettingBtn.gameObject
        elseif self.specialId == 8 then
            local dialog = self:GetSuspendDialog()
            if dialog then
                go = dialog.Env.BtnGuideBook.gameObject
            else
                go = self.refGuideDialog.Area_Sp_8.gameObject
            end
        elseif self.specialId == 9 then
            local _funcFindTarget = function()
                local dialogs = UIModule.CurrentScreen.dialogs
                for i, dialog in pairs(dialogs) do
                    if dialog.Argument.id == Constants.UITypeIds.UIGamePlayGuideBookDialog then
                        local lt = dialog.Env
                        if dialog and lt.listTabBtn then
                            go = lt.listTabBtn[2].controller.gameObject
                        end
                    end
                end
                return go
            end
            go = _funcFindTarget()
            local count = 0
            while isNull(go) and count <= 30 do
                go = _funcFindTarget()
                count = count + 1
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
            end
        else
            ---右上玩家战局设置
            go = self.refGuideDialog.Area_5
        end
    elseif type == Area.BossInfo then
        --- Boss 血条区域
        if pos == 1 then
            go = UIBattlingCtrlMgr:GetInstance():GetEleBreakLuaTable().Btn_ShowInfoPanel.gameObject
        elseif pos == 2 then
            go = self.refGuideDialog.Area_6_2
        else
            go = self.refGuideDialog.Area_6.parent.gameObject
            --go = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog().BossInfoRoot.gameObject
        end
    elseif type == Area.GuideBook then
        local dialog = self:GetPanelGuideBook()
        if pos == 1 then
            if dialog then
                go = dialog.goImgClosePanel
            end
        elseif pos == 2 then
            if dialog then
                go = dialog.rectPanelSkillPool.gameObject
            end
        elseif pos == 3 then
            if dialog then
                go = dialog.SkillCardSmallRoot.gameObject
            end
        end
    elseif type == Area.EnemySkill then
        --- 敌方队伍成员区域
        -- local enemyData = UIBattlingDataMgr:GetEnemyTeamList()
        local enemyData = self:GetEnemyTeamByWave(self.curWave)
        local enemyId = checkNumber(enemyData[pos].id)
        local battleInfoDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog()
        if battleInfoDialog then
            local roleNode = battleInfoDialog:GetCharacterNode(enemyId)
            if roleNode then
                go = roleNode.CharactorUseCardRoot
                local trans = go:GetChild(0)
                if not IsNull(trans) then
                    local goEnemySkill = trans.gameObject
                    if not isNull(goEnemySkill) then
                        go = self:CreateHighLightWithPOS(goEnemySkill.transform.position, Vector2.New(150, 150), 
                                self.refGuideDialog.Layer_ShowElement, "EnemySkill", 0, 0)
                    end
                end
            end
        end
    elseif type == Area.CharacterHpSlider then
        local id = pos % 10
        local playerData = UIBattlingDataMgr:GetPlayerTeamList()
        local playerId = checkNumber(playerData[id].id)
        local battleInfoDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog()
        if battleInfoDialog then
            local roleNode = battleInfoDialog:GetCharacterNode(playerId)
            if pos < 10 then
                -- 整个血条区域
                go = roleNode.controller.gameObject
            elseif pos < 20 then
                -- 属性图标
                go = roleNode.AttributeIcon.gameObject
            elseif pos < 30 then
                -- sp点区域
                go = roleNode.Root_SpPoint.gameObject
            end
        end
    elseif type == Area.EnemyHpSlider then
        local id = pos % 10
        -- local enemyData = UIBattlingDataMgr:GetEnemyTeamList()
        local enemyData = self:GetEnemyTeamByWave(self.curWave)
        local enemyId = checkNumber(enemyData[id].id)
        local battleInfoDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingInfoDialog()
        if battleInfoDialog then
            local roleNode = battleInfoDialog:GetCharacterNode(enemyId)
            if pos < 10 then
                -- 整个血条区域
                go = roleNode.controller.gameObject
            elseif pos < 20 then
                -- 属性图标
                go = roleNode.AttributeIcon.gameObject
            elseif pos < 30 then
                -- sp点区域
                go = roleNode.Root_SpPoint.gameObject
            end
        end
    elseif type == Area.SkillCatBtn then
        -- 猫球按钮
        local luaTBBattlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        go = luaTBBattlingDialog.RT_SkillCatNode.gameObject
    end
    return go
end

---SetShowAreaComponent
---@param root UnityEngine.GameObject 展示 的游戏物体
function GamePlayGuideMgr:SetShowAreaComponent(root)
    local isHad = KTool.HadComponent(root, typeof(Canvas))
    local comp = root:EnsureComponent(typeof(Canvas))
    comp.overrideSorting = true
    comp.sortingOrder = ORDER_IN_LAYER_SHOW_LAYER
    if IsNull(self.listCreateComponent) then
        self.listCreateComponent = {}
    end
    table.insert(self.listCreateComponent, { isHad = isHad, comp = comp })
end

---RevertComponent
---回收/还原 canvas 组件
function GamePlayGuideMgr:RevertComponent()
    if not IsNull(self.listCreateComponent) and #self.listCreateComponent > 0 then
        for i = #self.listCreateComponent, 1, -1 do
            if not IsNull(self.listCreateComponent[i]) then
                local item = self.listCreateComponent[i]
                if item.isHad then
                    self.listCreateComponent[i].comp.overrideSorting = false
                else
                    KTool.SafeDelete(self.listCreateComponent[i].comp)
                end
                self.listCreateComponent[i] = nil
            end
        end
        self.listCreateComponent = nil
    end
end

