---GetSkillCardPosInSkillPool
---获取交互卡牌 在 卡牌库的位置
---@param pos number 区域位置
function GamePlayGuideMgr:GetSkillCardPosInSkillPool(pos)
    local skillCardLine = pos > 5 and 2 or 1
    local skillCardPos = pos > 5 and pos - 5 or pos
    return skillCardLine, skillCardPos
end

---ShowMoveSkillCard
---展示移动卡牌
function GamePlayGuideMgr:ShowMoveSkillCard(data)
    --- BattlingDialog luaTable
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    --- SkillsPool LuaTable
    local tableSkillCard = battlingDialog.luaTableDialogSkillPool
    --- 确定拖拽控制器 和 拖拽目的地
    local aimLine, aimPos = self:GetSkillCardPosInSkillPool((self.typeSlider == SliderType.Horizontal) and data[2] or data[1])
    local ctrLine, ctrPos = self:GetSkillCardPosInSkillPool((self.typeSlider == SliderType.Horizontal) and data[1] or data[2])
    local skillCard_1 = tableSkillCard:GetSkillCardByPos(aimLine, aimPos).luaBehaviour
    local skillCard_2 = tableSkillCard:GetSkillCardByPos(ctrLine, ctrPos).luaBehaviour
    ---确定拖拽图标坐标
    local iconPos = Vector3.New((skillCard_1.transform.position.x + skillCard_2.transform.position.x) / 2,
            (skillCard_1.transform.position.y + skillCard_2.transform.position.y) / 2,
            (skillCard_1.transform.position.z + skillCard_2.transform.position.z) / 2)
    --- 确定拖拽图标 Z 轴旋转
    local numIconRotation = self.typeSlider == SliderType.Horizontal and 180 or -90
    self.refGuideDialog:SetPosGOStepIconSlide(iconPos, numIconRotation)
    self.dragSkillCard = skillCard_2
    --- battlingDialog 的 skillsPool 节点
    local rectOriginSkillsPool = battlingDialog.SkillCardsPool
    --- 克隆的 skillsPool 节点
    local goSkillsPool = KTool.CreateEmptyGameObject(self.refGuideDialog.Layer_Interactable.gameObject, "SkillCardRoot")
    --- 技能卡父节点的 rectInfo
    goSkillsPool.transform.position = rectOriginSkillsPool.transform.position
    goSkillsPool.transform.localScale = rectOriginSkillsPool.transform.localScale
    local eulerAngles = rectOriginSkillsPool.transform.localRotation.eulerAngles
    goSkillsPool.transform.localRotation = Quaternion.Euler(eulerAngles.x, eulerAngles.y, eulerAngles.z)
    local rectSkillsPool = KTool.GetOrAddComponent(goSkillsPool, typeof(RectTransform))
    rectSkillsPool.sizeDelta = rectOriginSkillsPool.sizeDelta
    --- 设置技能卡 控制器游戏物体
    local skillCardController = self:CreateSkillCardGO(skillCard_2, goSkillsPool.gameObject, "DragSkillCard")
    skillCardController.transform.localRotation = Quaternion.Euler(0, 0, 90)
    self.eventBattleMyCard = Events.AddListener(Constants.EventNames.BattleMyCard, function(data)
        if data.r == Constants.RecordType.MoveCard then
            self.booleanIsYield = false
        end
    end)
    KTool.GetOrAddComponent(skillCardController, typeof(GraphicRaycastReceiver))
    self:AddDragFun(skillCardController)
    self:AddOBJToListTempGO(skillCardController)
    self:YieldFunction()
end

---DragFun
---游戏物体拖动函数
---@param gesture HedgehogTeam.EasyTouch.Gesture
function GamePlayGuideMgr:DragFun(gesture)
    local uiCamera = UIModule.RootCanvas.defaultCamera
    local fatherTransform = self.dragSkillCard.transform.parent:GetComponent(typeof(RectTransform))
    local scale = fatherTransform.localScale
    local vec2
    local bool, vecNow = RectTransformUtility.ScreenPointToLocalPointInRectangle(fatherTransform, gesture.position, uiCamera, vec2)
    local x
    local y
    --- 竖直方向的 移动规则
    if self.typeSlider == SliderType.Vertical then
        x = self.goController.transform.anchoredPosition.x
        ----- 限制技能卡 Y
        if vecNow.y > 145 * scale.y then
            vecNow.y = 145 * scale.y
        end
        if vecNow.y < -145 * scale.y then
            vecNow.y = -145 * scale.y
        end
        y = vecNow.y
    else
        --- 水平方向上的移动规则
        local xValueLeft = self.valueDragCtrlXOrigin + 250 * scale.x
        local xValueRight = self.valueDragCtrlXOrigin - 50 * scale.x
        if vecNow.x < xValueRight then
            vecNow.x = xValueRight
        end
        if vecNow.x > xValueLeft then
            vecNow.x = xValueLeft
        end
        x = vecNow.x
        y = self.goController.transform.anchoredPosition.y
    end
    local vecSkillCard = Vector2.New(x, y)
    self.goController.transform.anchoredPosition = vecSkillCard
    self.dragSkillCard.Env:FuncSkillCardOnDrag(vecSkillCard)
end

function GamePlayGuideMgr:DragFree(gesture)
    local uiCamera = UIModule.RootCanvas.defaultCamera
    local fatherTransform = self.dragSkillCard.transform.parent:GetComponent(typeof(RectTransform))
    --local scale = fatherTransform.localScale
    local vec2
    local bool, vecNow = RectTransformUtility.ScreenPointToLocalPointInRectangle(fatherTransform, gesture.position, uiCamera, vec2)
    if UIBattlingTools.GetSkillCardPosOutOfRange(vecNow) then
        self:DragFreeCancel()
        return
    end
    self.goController.transform.anchoredPosition = vecNow
    self.dragSkillCard.Env:FuncSkillCardOnDrag(vecNow)
end

function GamePlayGuideMgr:DragEndFree()
    local skillCardAnchoredPosX = self.dragSkillCard.transform.anchoredPosition.x
    local skillCardAnchoredPosY = self.dragSkillCard.transform.anchoredPosition.y
    local targetPosX =  self.freeDragTargetPos.anchoredPosition.x
    local targetPosY = self.freeDragTargetPos.anchoredPosition.y
    if skillCardAnchoredPosX >= targetPosX - Constants.EDGE_OF_EXCHANGE_SKILLCARD
        and skillCardAnchoredPosX <= targetPosX + Constants.EDGE_OF_EXCHANGE_SKILLCARD
        and skillCardAnchoredPosY >= targetPosY - Constants.EDGE_OF_EXCHANGE_SKILLCARD 
        and skillCardAnchoredPosY <= targetPosY + Constants.EDGE_OF_EXCHANGE_SKILLCARD
    then
        self.booleanIsYield = false
        self.dragSkillCard.Env:OnDragEndFun()
    else
        self:DragFreeCancel()
    end
end

function GamePlayGuideMgr:DragFreeCancel()
    if not isNull(self.goController) then
        local uiDrag = KTool.GetComponent(self.goController, typeof(UIDrag))
        if not isNull(uiDrag) then
            uiDrag:StopDrag()
        end
        self.goController.transform.position = self.freeDragOriginPos.transform.position
    end
    self.dragSkillCard.Env:OnInteractiveInvalid()
end

---AddDragFun
---游戏物体添加拖动函数
---@param aimGO UnityEngine.GameObject
function GamePlayGuideMgr:AddDragFun(aimGO, isFreeDrag)
    isFreeDrag = checkBool(isFreeDrag)
    KTool.GetOrAddComponent(aimGO, typeof(CanvasRenderer))
    self.goController = aimGO
    --- 水平拖拽 技能卡 X 初始坐标
    self.valueDragCtrlXOrigin = self.goController.transform.anchoredPosition.x
    local compDrag = KTool.GetOrAddComponent(aimGO, typeof(UIDrag))
    compDrag.onDragStart:AddListener(function(gesture)
        self.dragSkillCard.Env:OnDragStartFun(gesture.position)
    end)
    compDrag.onDrag:AddListener(Bind(self, isFreeDrag and self.DragFree or self.DragFun))
    compDrag.onDragEnd:AddListener(Bind(self, isFreeDrag and self.DragEndFree or self.DragEndCommon))
end

function GamePlayGuideMgr:DragEndCommon()
    if not isNull(self.dragSkillCard) then
        self.dragSkillCard.Env:OnDragEndFun()
    end
end

function GamePlayGuideMgr:LongTapEntry()
    if self.highLightAreaData[1] == Area.Enemy
    or self.highLightAreaData[1] == Area.Character then
        self:LongTapCharacter()
    elseif self.highLightAreaData[1] == Area.SkillsPool then
        self:LongTapSkillCard()
    elseif self.highLightAreaData[1] == Area.SkillCatBtn then
        self:LongTapSkillCatBtn()
    else
        self:SetClickDialogPass()
    end
end

function GamePlayGuideMgr:LongTapSkillCatBtn()
    local areaClick = self.listStepClick[1]
    if IsNull(areaClick) then return end
    -- 设置长按的手指动画
    self.refGuideDialog:SetPosGOStepIconLongTap(areaClick)

    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    -- 长按事件
    local func = function()
        battlingDialog.LT_SkillCatNode:OnPress()
        local tipsPanel = battlingDialog.RT_CatBallSkillTipsPanel.gameObject
        local comp = tipsPanel:EnsureComponent(typeof(Canvas))
        comp.overrideSorting = true
        comp.sortingOrder = SKILL_TIPS_SHOW_LAYER
    end
    -- 长按结束的回调
    local pressEnd = function()
        battlingDialog.LT_SkillCatNode:OnPressEnd()
        self.booleanIsYield = false
    end
    local tempGO = self:CreateLongTapGO(areaClick, self.refGuideDialog.Layer_Interactable, "LongTapSkillCard", Bind(self, func), Bind(self, pressEnd))
    self:AddOBJToListTempGO(tempGO)
    self:YieldFunction()
end

---LongTapEntry
---技能卡长按功能 过程步骤 入口
function GamePlayGuideMgr:LongTapSkillCard()
    self.skillCardLB = self.listStepClick[1].luaBehaviour
    local tableSkillCard = self.skillCardLB.Env
    local skillCardGO = self.skillCardLB.gameObject
    self.refGuideDialog:SetPosGOStepIconLongTap(skillCardGO)
    -- 长按回调
    local funcShowSkillDesc = function()
        -- 打开技能提示
        local skillInfoPanel = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().SkillTipsRoot.gameObject
        tableSkillCard:OnSkillCardPress()
        KTool.SetActive(skillInfoPanel, true)
        local comp = skillInfoPanel:EnsureComponent(typeof(Canvas))
        comp.overrideSorting = true
        comp.sortingOrder = SKILL_TIPS_SHOW_LAYER
    end
    -- 长按结束的回调
    local pressEnd = function()
        self.booleanIsYield = false
        -- 关闭技能提示
        local skillInfoPanel = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog().SkillTipsRoot.gameObject
        tableSkillCard:OnInteractiveInvalid()
        KTool.SetActive(skillInfoPanel, false)
    end
    local tempGO = self:CreateLongTapGO(skillCardGO, self.refGuideDialog.Layer_Interactable, 
        "LongTapSkillCard", Bind(self, funcShowSkillDesc), Bind(self, pressEnd))
    self:AddOBJToListTempGO(tempGO)
    ---出现跳步点击区域
    self:YieldFunction()
end

--- 长按角色
function GamePlayGuideMgr:LongTapCharacter()
    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
    local characterType = self.highLightAreaData[1]
    local areaClick = self.listStepClick[1]
    local roleId = self.listIdsCharacter[1]
    if IsNull(areaClick) or IsNull(roleId) then return end
    -- 设置长按的手指动画
    self.refGuideDialog:SetPosGOStepIconLongTap(areaClick)
    -- 长按事件
    local func = function()
        battlingDialog.longTapCharacterData = BattleViewMgr:FindRoleView(roleId)
        battlingDialog:ShowCharacterInfoDialog()
        self.booleanIsYield = false
    end
    local tempGO = self:CreateLongTapGO(areaClick, self.refGuideDialog.Layer_Interactable, "LongTapSkillCard", Bind(self, func))
    self:AddOBJToListTempGO(tempGO)
    self:YieldFunction()
end

