function GamePlayGuideMgr:GetPanelGuideBook()
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, dialog in pairs(dialogs) do
        if dialog.Argument.id == Constants.UITypeIds.UIGamePlayGuideBookDialog then
            return dialog.Env
        end
    end
    return nil
end

function GamePlayGuideMgr:CleanGuideBook()
    local _stepData = GamePlayGuideConfMgr:GetGuideStepData(self.stepId)
    local _ifGuide = _stepData.ifGuide
    local _highLightAreas = _stepData.highLightAreas
    local _funcGetAreaHad = function(highLightAreas)
        for i, areaData in pairs(highLightAreas) do
            if areaData == Area.GuideBook then
                return true
            end
        end
        return false
    end
    if _ifGuide and _ifGuide < 1 and (not _funcGetAreaHad(_highLightAreas)) then
        self:ActionCloseGuideBook()
    end
end

function GamePlayGuideMgr:ActionShowGuideBook()
    ---打开战中指南指定页
    local _stepData = GamePlayGuideConfMgr:GetGuideStepData(self.stepId)
    if _stepData then
        local ifGuide = _stepData.ifGuide
        if ifGuide and ifGuide > 0 then
            self:SetGuideBookShow(checkInt(ifGuide))
        end
    end
end

function GamePlayGuideMgr:SetGuideBookShow(indexTab)
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, dialog in pairs(dialogs) do
        if dialog.Argument.id == Constants.UITypeIds.UIGamePlayGuideBookDialog then return end
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIGamePlayGuideBookDialog, parameters = { indexTab = indexTab, showType = 2 }})
end

function GamePlayGuideMgr:ActionCloseGuideBook()
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, dialog in pairs(dialogs) do
        if dialog.Argument.id == Constants.UITypeIds.UIGamePlayGuideBookDialog then
            UIModule.CloseDialog(dialog)
        end
    end
end

function GamePlayGuideMgr:RegionCoordinateTranslate(stepData)
    local _highLightArea = nil
    if stepData then
        local _regionCoordinate = stepData.regionCoordinate
        if _regionCoordinate then
            local _goPos = _regionCoordinate.Position
            local _goSize = Vector2.New(_regionCoordinate.Size[1], _regionCoordinate.Size[2])
            _highLightArea = self:CreateHighLightWithPOS(Vector3.zero, _goSize, self.refGuideDialog.Layer_ShowElement, "ScreenPosArea", 0, 0)
            if not isNull(_highLightArea) then
                local _AposX = _goPos[1]
                local _AposY = _goPos[2]
                _highLightArea.transform.anchoredPosition = Vector2.New(_AposX, _AposY)
                _highLightArea.transform.localPosition = Vector3.New(_highLightArea.transform.localPosition.x, _highLightArea.transform.localPosition.y, 0)
            end
        end
    end
   return _highLightArea
end

function GamePlayGuideMgr:IsChapterZero()
    return checkBool(self.questId == checkNumber(10000))
end

function GamePlayGuideMgr:SetPTCGuideMove(posEnd)
    self:PTCMoveCancel()
    local goPTCGuide = self:LoadPTCGuide(posEnd)
    if self.indexCallPTCGuide < 2 then return end
    local posStart = self.refGuideDialog.tableDescWithCharacter.Img_WithRole.transform.position
    goPTCGuide.transform.position = posStart
    KTool.SetActive(goPTCGuide, true)
    local TAG_TWEEN = "GUIDE_SIN_MOVE"
    self.tweenPTCGuide = goPTCGuide.transform:DOMove(posEnd, 0.3):OnComplete(function()
        KTool.SetActive(goPTCGuide, false)
        local goPTCBoom = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_GUIDE_BOOM, self.refGuideDialog.Layer_ShowElement.gameObject, 1)
        goPTCBoom.transform.position = posEnd
    end)
    self.tweenPTCGuide.stringId = TAG_TWEEN
end

function GamePlayGuideMgr:LoadPTCGuide(pos)
    self.indexCallPTCGuide = self.indexCallPTCGuide + 1
    if isNull(self.goPTCGuide) then
        self.goPTCGuide = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_GUIDE_MOVE, self.refGuideDialog.Layer_ShowElement.gameObject, 9999)
        if pos then
            self.goPTCGuide.transform.position = pos
        end
    end
    KTool.SetActive(self.goPTCGuide, false)
    return self.goPTCGuide
end

function GamePlayGuideMgr:PTCMoveCancel()
    xTry(function()
        DOTween.Pause(TAG_TWEEN)
        DOTween.Kill(TAG_TWEEN)
        if not isNull(self.goPTCGuide) then
            KTool.SetActive(self.goPTCGuide, false)
        end
    end)
end

function GamePlayGuideMgr:GetSuspendDialog()
    local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIBattlingBackToFightReadyDialog)
    return dialog
end

function GamePlayGuideMgr:CleanSuspendDialog()
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, dialog in pairs(dialogs) do
        if dialog.Argument.id == Constants.UITypeIds.UIBattlingBackToFightReadyDialog then
            UIModule.CloseDialog(dialog)
        end
    end
end

--- 验证是否可以播放
---@param stepId any
function GamePlayGuideMgr:ValidatePlayable(stepId)
    local playData = GamePlayGuideConfMgr:GetGuideStepData(stepId)
    local area = playData.highLightAreas[1]

    if area == Area.SkillCatBtn then
        local cat = BattleViewMgr:GetSkillCat(BattleInfo.myCamp, 1)
        return isNotNull(cat)
    end
    return true
end

--- 获取指定波次的敌人列表
---@param wave any
function GamePlayGuideMgr:GetEnemyTeamByWave(wave)
    local enemyData = UIBattlingDataMgr:GetEnemyTeamList()
    local curWaveEnemyData = {}
    for i, v in ipairs(enemyData) do
        if v.wave == wave then
            table.insert(curWaveEnemyData, v)
        end
    end
    return curWaveEnemyData
end

function GamePlayGuideMgr:HasRivalGuide()
    return isNotNull(self.dataPlay[0]) and isNotNull(self.dataPlay[0][0])
end

function GamePlayGuideMgr:GetRivalGuide(index)
    local stepId = self.dataPlay[0][0][index]
    local playData = GamePlayGuideConfMgr:GetGuideStepData(stepId)
    return playData
end

return GamePlayGuideMgr